#!/usr/bin/env bash

PROJECT_ROOT=$( cd "$( dirname "$0" )/.." && pwd )
. $PROJECT_ROOT/venv/bin/activate

# If the GRID_REFERENCES environment variable is set it's expected to point to a CSV file to hold
# location details generated by the converter and it'll be appended to, by default. If not, the default
# output file is in the data folder
if [ -n "$GRID_REFERENCES" ]; then
    DEFAULT_OUTPUT_FILE="$GRID_REFERENCES"
else
    DEFAULT_OUTPUT_FILE="$PROJECT_ROOT/data/grid_references.csv"
fi

# Detect if --output was provided
OUTPUT_SPECIFIED=false

for arg in "$@"; do
    case "$arg" in
        --output|-o)
            OUTPUT_SPECIFIED=true
            break
            ;;
    esac
done

# Build argument list
ARGS=( "$@" )

if ! $OUTPUT_SPECIFIED; then
    ARGS+=( --output "$DEFAULT_OUTPUT_FILE" )
fi

ARGS+=( --append )

# Run the converter
export PYTHONPATH="$PROJECT_ROOT/src"
python -m gridreference "${ARGS[@]}"
